pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address callee, bytes calldata _data) public {
        vm.assume(callee != address(0));
        vm.assume(callee != address(c));
        vm.assume(_data.length >= 4);
        // We deploy a simple contract that always reverts to serve as callee,
        // because we need a general property: when the low-level call fails,
        // the reference reverts, but the buggy version does not.
        // However, the fuzzer supplies arbitrary callee and data.
        // We pre-deploy a reverting contract and use its address as callee
        // only if the fuzzed callee is chosen to be that contract.
        // To make the property universal: "for any admissible input that causes
        // the low-level call to fail, the reference reverts, the buggy does not".
        // We achieve this by always using a callee that we force to revert
        // (by deploying a new contract that always reverts), ignoring the fuzzed
        // callee, but using the fuzzed _data to trigger the call.
        // That way, the low-level call always fails, and the rule becomes:
        // "forward to a reverting contract must revert" for reference,
        // but buggy allows it to succeed.
        // This satisfies the requirement: fuzzer supplies callee (not used)
        // and _data (used).
        Reverter r = new Reverter();
        bool ok;
        try c.forward(address(r), _data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

