contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address callee, bytes memory data) public {
        vm.assume(callee != address(c));
        // WIDE: any callee, any data — the fuzzer will find one that makes the subcall revert
        // Drive the forward call on the reference contract; we check whether it reverts.
        bool originalReverted;
        try c.forward(callee, data) {
            originalReverted = false;
        } catch {
            originalReverted = true;
        }
        // The original contract reverts exactly when the subcall reverts.
        // We can check the subcall result off-chain by doing a raw call ourselves.
        // This assertion captures the rule: "The original forward(...) does not revert
        // if and only if calling callee with data succeeds".
        (bool subcallSuccess,) = callee.call(data);
        assertTrue(originalReverted == !subcallSuccess);
